mapper.select:

SELECT a.recipient_name, a.phone, a.country_code, a.state_province, a.city,
       a.district, a.address_line1, a.address_line2, a.postal_code, a.label
FROM shipping_addresses a
JOIN carts c ON c.selected_address_id = a.id
WHERE c.user_id = #{customerId}
  AND a.user_id = #{customerId}
